#include <vector>
#include <algorithm>

using namespace std;

const int MAXN = 100;

vector<int> adj[MAXN]; // graph representation as an adjacency list
int n;                  // number of edges

void dijkstra() {
    priority_queue<int, vector<int>, Compare> queue;
    queue.push(0); // source edge
    vector<bool> visited(MAXN, false);

    while (!queue.empty()) {
        int u = queue.top();
        queue.pop();

        if (visited[u]) {
            continue; // edge has already been visited
        }

        visited[u] = true;

        for (int v : adj[u]) {
            if (!visited[v]) {
                queue.push(v); // add unvisited neighbor to the queue
            }
        }
    }
}

int Compare(int a, int b) {
    return abs(a - b); // use absolute value to break ties
}

