Here's a piece of C++ code that exhibits curious behavior.

For some reason, sorting the data (before the timed region) makes the outer loop run almost six times faster:

#include <algorithm>
#include <ctime>
#include <iostream>

int main()
{
    // Create data
    const unsigned arraySize = 32768;
    int data[arraySize];

    for (unsigned c = 0; c < arraySize; ++c)
        data[c] = std::rand() % 256;

    // !!! With this, the next loop runs faster.
    std::sort(data, data + arraySize);

    // Test
    clock_t start = clock();
    long long sum = 0;
    for (unsigned i = 0; i < 100000; ++i)
    {
        for (unsigned c = 0; c < arraySize; ++c)
        {   // Main loop.
            if (data[c] >= 128)
                sum += data[c];
        }
    }

    double elapsedTime = static_cast<double>(clock()-start) / CLOCKS_PER_SEC;

    std::cout << elapsedTime << '
';
    std::cout << "sum = " << sum << '
';
}
Without std::sort(data, data + arraySize); the code runs in 11.54 seconds.
With the sorted data, the code runs in 1.93 seconds.
(Sorting itself takes longer than one pass over the data, so it's not worth it in practice, at least not for a single iteration over the data. )

